def setLights(light_port_number, lights_rgb_data):
    hex_data = f"0401dc4a0100080162820100ffffffff0{light_port_number}00000000020000"
    full_payload_length = 48 + 1024

    for rgb_vals in lights_rgb_data: 
        for val in rgb_vals:        
            if isinstance(val, str): # if its already a hex string append
                hex_data += val
            else: # if its a number between 0-255 convert it to hex
                hex_str = format(val, '02x')
                print(hex_str)
                hex_data += hex_str
                
    remaining_payload_length = full_payload_length - len(hex_data) 
    for i in range(remaining_payload_length):
        hex_data += "0"

    # Convert hex data to bytes
    message = binascii.unhexlify(hex_data)

    print(len(hex_data))
    # Send the packet
    sock.sendto(message, (ip_address, port))


setLights(1, [[255,0,0], [0,255,0], [0,0,255]])
time.sleep(1)
setLights(1, [])
